import{_ as s,l as i,o as e,c as n,v as t,p as l,x as r,d as h,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"二叉查找树","description":"","frontmatter":{"title":"二叉查找树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bst.md","filePath":"cs/bst.md","lastUpdated":1789023840000}'),p={name:"cs/bst.md"};function A(B,a,_,m,T,E){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="二叉查找树" tabindex="-1">二叉查找树 <a class="header-anchor" href="#二叉查找树" aria-label="Permalink to &quot;二叉查找树&quot;">​</a></h1><div class="epigraph"><p>左子树都小于根、右子树都大于根，查找就沿着一条根到叶的路径走，步数等于高度。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms；Knuth, TAOCP 卷 3 整理</footer></div><p><a href="/cs/amortized-analysis">上一课</a>让动态数组的端操作摊还 \\(\\Theta(1)\\)。按下标已经解决；按键查找在无序数组或链表上仍是 \\(\\Theta(n)\\)。<a href="/cs/tree-as-acyclic">树作为无环连通图</a>已经有树。<a href="/cs/asymptotic-notation">渐近记号</a>把高度写成 \\(h\\)。本课不重讲摊还。缺口是有序字典的第一种树表示：二叉查找树（BST）不变式，查找/插入沿比较路径。平衡不在本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数组有序可用二分，但插入要搬移。链表插入廉价，不能二分。缺口是：节点带左右孩子，<strong>中序遍历恰好是键的排序</strong>，从而比较一次丢掉一边。合同：查找、插入、删除与后继。</p><p>没有平衡时，\\(h\\) 最坏 \\(n\\)（插成链），最坏查找 \\(\\Theta(n)\\)，退回链表。本课必须把这个边界说清，否则后课 AVL 没有动机。</p><p><span class="marginnote">随机插入下期望高度 \\(O(\\log n)\\)，那是期望分析，不是最坏合同。本课最坏按 \\(h\\) 写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>节点：键、可选卫星数据、左、右、可选父。不变式：左子树键 $\\lt $ 根 $\\lt $ 右子树键（或非严格，须统一）。查找：从根比较，小走左、大走右，空则失败。插入：失败路径的空位挂新叶。</p>',9)),(e(),l(c,null,{default:r(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%A0%B9%22%5D%20--%3E%20L%5B%22%E5%B7%A6%EF%BC%9A%E7%9A%86%E5%B0%8F%E4%BA%8E%E6%A0%B9%22%5D%0A%20%20R%20--%3E%20RI%5B%22%E5%8F%B3%EF%BC%9A%E7%9A%86%E5%A4%A7%E4%BA%8E%E6%A0%B9%22%5D%0A%20%20L%20--%3E%20LL%5B%22%E7%BB%A7%E7%BB%AD%20BST%22%5D%0A%20%20RI%20--%3E%20RR%5B%22%E7%BB%A7%E7%BB%AD%20BST%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>删除分三支：叶、单子、双子（用后继顶替）。本课承认双子删除要找后继，不把所有旋转请进来。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>中序遍历在 \\(\\Theta(n)\\) 内输出有序列，这是链表扫不到的「有序」加树结构。字典操作复杂度 \\(\\Theta(h)\\)，不是 \\(\\Theta(\\log n)\\)，除非另证 \\(h\\)。后课旋转保持不变式同时降 \\(h\\)。</p><p>与<a href="/cs/locality-principle">局部性原理</a>：指针树同样追逐；节点池或 B 树才会把比较装进 cache 行。本课先保证正确性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入红黑位、不引入 AVL 平衡因子。也不把 BST 当成优先队列——无序堆更适合「只要最小」。重复键、卫星数据的相等策略须事先约定。</p><p>后课默认：有序字典可以放在 BST 里，代价随高度。高度无保证时，必须平衡。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BST 不变式让比较丢掉一边；步数是高度 \\(h\\)。</li><li>最坏 \\(h=\\Theta(n)\\)；期望随机插入才对数。</li><li>旋转维持不变式并降高，是下一课 AVL。</li><li>出处：Cormen et al. 第 12 章；Knuth, <em>TAOCP</em> 卷 3。</li></ul>',9))])}const b=s(p,[["render",A]]);export{f as __pageData,b as default};
